                            "                        form DATE[-DATE] where DATE" + EOL +
                            "                        has form YYYY[MM[DD]]";
    //@formatter:on

    final StringBuffer sb = new StringBuffer();
    new HelpFormatter().renderWrappedText(sb, width, padding, text);
    assertEquals(expected, sb.toString(), "single line padded text 2");
}

