            .build();

    // Deprecated option d1 (no explicit attributes)
    Option opt1 = Option.builder()
            .option("d1")
            .deprecated()
            .build();

    // Deprecated option d2 with explicit attributes
    Option opt2 = Option.builder()
            .option("d2")
            .deprecated(DeprecatedAttributes.builder()
                    .setForRemoval(true)
                    .setSince("1.0")
                    .setDescription("Do this instead.")
                    .get())
            .build();

    // Non‑deprecated option a
    Option opt3 = Option.builder()
            .option("a")
            .build();

    CommandLine cl = assertDoesNotThrow(
            () -> parser.parse(new Options()
                    .addOption(opt1)
                    .addOption(opt2)
                    .addOption(opt3),
                    new String[] {"-d1", "-d2", "-a"}),
            "Parsing command line should not throw a ParseException");

    ParseResult result = new ParseResult();
    result.handler = handler;
    result.cl = cl;
    result.opt1 = opt1;
    result.opt2 = opt2;
    result.opt3 = opt3;
    return result;
}

@Test
public void testDeprecatedHandlerTriggersForDeprecatedOptions() {
    ParseResult r = parseWithDeprecatedHandler();
    assertTrue(r.handler.contains(r.opt1),
            "Handler should contain deprecated option opt1");
    assertTrue(r.handler.contains(r.opt2),
            "Handler should contain deprecated option opt2");
}

@Test
public void testDeprecatedHandlerDoesNotTriggerForNonDeprecatedOption() {
    ParseResult r = parseWithDeprecatedHandler();
    assertFalse(r.handler.contains(r.opt3),
            "Handler should not contain non‑deprecated option opt3");
}

@Test
public void testParsingRecognizesAllOptions() {
    ParseResult r = parseWithDeprecatedHandler();
    assertTrue(r.cl.hasOption(r.opt1.getOpt()),
            "CommandLine should contain option d1");
    assertTrue(r.cl.hasOption(r.opt2.getOpt()),
            "CommandLine should contain option d2");
    assertTrue(r.cl.hasOption(r.opt3.getOpt()),
            "CommandLine should contain option a");
}

