@Test
public void testIndexOf() {
    JsonArray a = new JsonArray();
    // Add the same value twice to test indexOf vs. lastIndexOf
    a.add(1);
    a.add(1);

    List<JsonElement> list = a.asList();
    assertThat(list.indexOf(new JsonPrimitive(1)))
        .named("indexOf(JsonPrimitive(1)) should return the first occurrence index 0")
        .isEqualTo(0);
    assertThat(list.indexOf(new JsonPrimitive(2)))
        .named("indexOf(JsonPrimitive(2)) should return -1 when the element is absent")
        .isEqualTo(-1);
    assertThat(list.indexOf(null))
        .named("indexOf(null) should return -1 when searching for null")
        .isEqualTo(-1);

    @SuppressWarnings({"unlikely-arg-type", "CollectionIncompatibleType"})
    int indexOfInt = list.indexOf(1); // should only contain JsonPrimitive(1)
    assertThat(indexOfInt)
        .named("indexOf(Integer) should return -1 because the list contains only JsonPrimitive objects")
        .isEqualTo(-1);

    assertThat(list.lastIndexOf(new JsonPrimitive(1)))
        .named("lastIndexOf(JsonPrimitive(1)) should return the last occurrence index 1")
        .isEqualTo(1);
    assertThat(list.lastIndexOf(new JsonPrimitive(2)))
        .named("lastIndexOf(JsonPrimitive(2)) should return -1 when the element is absent")
        .isEqualTo(-1);
    assertThat(list.lastIndexOf(null))
        .named("lastIndexOf(null) should return -1 when searching for null")
        .isEqualTo(-1);
}

