/**
 * Functional interface to allow lambda expressions that throw checked exceptions.
 */
@FunctionalInterface
private interface ThrowingSupplier<T> {
    T get() throws Exception;
}

/**
 * Executes the supplied code and fails the test if any exception is thrown.
 *
 * @param supplier the code to execute
 * @param <T>      the type of the result
 * @return the result of the supplier if no exception occurs
 */
private static <T> T assertDoesNotThrow(ThrowingSupplier<T> supplier) {
    try {
        return supplier.get();
    } catch (Throwable t) {
        fail("Unexpected exception: " + t);
        return null; // Unreachable, added to satisfy compiler
    }
}

