@ParameterizedTest(name = "Literal \"{0}\" should be parsed as {1}")
@CsvSource({
    "'True', TRUE",
    "'TruE', TRUE",
    "'False', FALSE",
    "'FALSE', FALSE",
    "'NULL', NULL",
