})
void testMixedCaseLiteral(String literal, ExpectedKind kind) {
    assertDoesNotThrow(() -> {
        JsonReader reader = new JsonReader(reader("[" + literal + "]"));
        reader.beginArray();
        switch (kind) {
            case TRUE:
                assertWithMessage("Literal \"%s\" should be parsed as true.", literal)
                    .that(reader.nextBoolean()).isTrue();
                break;
            case FALSE:
                assertWithMessage("Literal \"%s\" should be parsed as false.", literal)
                    .that(reader.nextBoolean()).isFalse();
                break;
            case NULL:
                assertWithMessage("Literal \"%s\" should be parsed as null.", literal)
                    .that(reader.peek()).isEqualTo(JsonToken.NULL);
                reader.nextNull();
                break;
        }
        reader.endArray();
        assertWithMessage("After reading literal \"%s\", reader should be at END_DOCUMENT.", literal)
            .that(reader.peek()).isEqualTo(JsonToken.END_DOCUMENT);
    });
}

