/** Functional interface allowing checked exceptions in lambda expressions. */
@FunctionalInterface
private interface ThrowingRunnable {
    void run() throws Exception;
}

/** Asserts that the supplied runnable completes without throwing any exception. */
private static void assertDoesNotThrow(ThrowingRunnable runnable) {
    try {
        runnable.run();
    } catch (Throwable t) {
        throw new AssertionError("Unexpected exception thrown during test execution", t);
    }
}

private static final String[] MALFORMED_NUMBERS = {
    "some text",
    "",
    ".",
    "00",
    "01",
    "-00",
    "-",
    "--1",
    "+1", // plus sign is not allowed for integer part
    "+",
    "1,0",
    "1,000",
    "0.", // decimal digit is required
    ".1", // integer part is required
    "e1",
    ".e1",
    ".1e1",
    "1e-",
    "1e+",
    "1e--1",
    "1e+-1",
    "1e1e1",
    "1+e1",
    "1e1.0",
};

@Test
public void testMalformedNumbers() {
    assertMalformedNumbers();
}

private void assertMalformedNumbers() {
    for (String malformedNumber : MALFORMED_NUMBERS) {
        JsonWriter jsonWriter = new JsonWriter(new StringWriter());
        IllegalArgumentException e = assertThrows(
                IllegalArgumentException.class,
                () -> jsonWriter.value(new LazilyParsedNumber(malformedNumber)));
        assertThat(e)
                .hasMessageThat()
                .isEqualTo(
                        "String created by class com.google.gson.internal.LazilyParsedNumber is not a valid"
                                + " JSON number: "
                                + malformedNumber);
    }
}

