public void adoptedFormsRetainInputs() {
    // test for https://github.com/jhy/jsoup/issues/249
    final int EXPECTED_FORM_DATA_SIZE = 3;
    final int FIRST_INDEX = 0;
    final int SECOND_INDEX = 1;
    final int THIRD_INDEX = 2;

    String html = "<html>\n" +
            "<body>  \n" +
            "  <table>\n" +
            "      <form action=\"/hello.php\" method=\"post\">\n" +
            "      <tr><td>User:</td><td> <input type=\"text\" name=\"user\" /></td></tr>\n" +
            "      <tr><td>Password:</td><td> <input type=\"password\" name=\"pass\" /></td></tr>\n" +
            "      <tr><td><input type=\"submit\" name=\"login\" value=\"login\" /></td></tr>\n" +
            "   </form>\n" +
            "  </table>\n" +
            "</body>\n" +
            "</html>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    List<Connection.KeyVal> data = form.formData();

    assertEquals("Form should contain exactly 3 input elements", EXPECTED_FORM_DATA_SIZE, data.size());
    assertEquals("First input name should be 'user'", "user", data.get(FIRST_INDEX).key());
    assertEquals("Second input name should be 'pass'", "pass", data.get(SECOND_INDEX).key());
    assertEquals("Third input name should be 'login'", "login", data.get(THIRD_INDEX).key());
}

