    "'ab',                 'toto',            false",
    "'     ',              'toto',            false",
    "'tototo',             'toto',            false",
    "'raulpismuth  ',      'raulpismuth',    true",
    "' abcd  raulpismuth efgh ', 'raulpismuth', true",
    "' abcd efgh raulpismuth',   'raulpismuth', true",
    "' abcd efgh raulpismuth ',  'raulpismuth', true"
})
void testHasClassDomMethods(String classAttribute, String queryClass, boolean expected) {
    Tag tag = Tag.valueOf("a");
    Attributes attribs = new Attributes();
    attribs.put("class", classAttribute);
