    boolean hasClass = el.hasClass(queryClass);
    if (expected) {
        assertTrue(hasClass,
            () -> String.format("Expected element to HAVE class '%s' when attribute value is '%s'.", queryClass, classAttribute));
    } else {
        assertFalse(hasClass,
            () -> String.format("Expected element to NOT HAVE class '%s' when attribute value is '%s'.", queryClass, classAttribute));
    }
}

