private Element[] setupElements() {
    Document doc = Jsoup.parse("<div class=foo>Text</div>");
    Element original = doc.select("div").first();
    Element clone = doc.clone().select("div").first();
    return new Element[]{original, clone};
}

@Test
public void supportsClone_preservesClassAndText() {
    Element[] elems = setupElements();
    Element original = elems[0];
    Element clone = elems[1];

    assertTrue("Original element should have class 'foo' before cloning", original.hasClass("foo"));
    assertTrue("Cloned element should retain class 'foo'", clone.hasClass("foo"));
    assertEquals("Cloned element should retain original text 'Text'", "Text", clone.text());
}

@Test
public void supportsClone_originalModificationDoesNotAffectClone() {
    Element[] elems = setupElements();
    Element original = elems[0];
    Element clone = elems[1];

    original.removeClass("foo");
    original.text("None");

    assertFalse("Original element should not have class 'foo' after removal", original.hasClass("foo"));
    assertEquals("Original element text should be updated to 'None'", "None", original.text());
    assertTrue("Cloned element should still have class 'foo' after original modification", clone.hasClass("foo"));
    assertEquals("Cloned element text should remain 'Text' after original modification", "Text", clone.text());
}

