/** Helper constants */
private static final int EXPECTED_VISIBLE_ATTRIBUTE_COUNT = 2;

/** Helper method to create a sample Attributes instance with internal entries */
private Attributes createSampleAttributes() {
    Attributes attrs = new Attributes();
    attrs.put("One", "One");
    attrs.put(Attributes.internalKey("baseUri"), "example.com");
    attrs.put("Two", "Two");
    attrs.put(Attributes.internalKey("another"), "example.com");
    return attrs;
}

/** Helper method to count the number of attributes exposed by the iterator (i.e., non‑internal) */
private int countVisibleAttributes(Attributes attrs) {
    int count = 0;
    for (Attribute ignored : attrs) {
        count++;
    }
    return count;
}

/** Verify that the iterator returns only the non‑internal keys in insertion order */
@Test
void testIteratorSkipsInternal_iteratesInOrder() {
    Attributes attrs = createSampleAttributes();
    Iterator<Attribute> it = attrs.iterator();

    Assertions.assertTrue(it.hasNext(),
            "Iterator should have a first element (non‑internal attribute \"One\").");
    Assertions.assertEquals("One", it.next().getKey(),
            "First attribute returned by iterator should be the key \"One\".");

    Assertions.assertTrue(it.hasNext(),
            "Iterator should have a second element (non‑internal attribute \"Two\").");
    Assertions.assertEquals("Two", it.next().getKey(),
            "Second attribute returned by iterator should be the key \"Two\".");

    Assertions.assertFalse(it.hasNext(),
            "Iterator should have no further elements after the two non‑internal attributes.");
}

