private List<TextNode> getAllTextNodes(Document doc) {
    List<TextNode> result = new ArrayList<>();
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                result.add((TextNode) node);
            }
        }
    }
    return result;
}

/** Helper that asserts every TextNode in the list has non‑blank text. */
private void assertAllTextNodesNonBlank(List<TextNode> textNodes) {
    for (TextNode tn : textNodes) {
        assertFalse(StringUtil.isBlank(tn.text()),
                "TextNode text should not be blank (found: \"" + tn.text() + "\")");
    }
}

/** Condition method used by @EnabledIf – always returns true. */
private static boolean alwaysEnabled() {
    return true;
}

@Test
@EnabledIf("alwaysEnabled")
public void testHasTextWhenIterating_FirstTextNodeContent() {
    Document doc = createDocument();
    TextNode first = getFirstTextNode(doc);
    assertNotNull(first, "Expected to find at least one TextNode in the document");
    assertEquals("One ", first.text(), "First TextNode text should be \"One \"");
    assertEquals("One ", first.getWholeText(), "First TextNode whole text should be \"One \"");
}

@Test
@EnabledIf("alwaysEnabled")
public void testHasTextWhenIterating_AllTextNodesNonBlank() {
    Document doc = createDocument();
    List<TextNode> textNodes = getAllTextNodes(doc);
    assertFalse(textNodes.isEmpty(), "Expected at least one TextNode in the document");
    assertAllTextNodesNonBlank(textNodes);
}

